public class Solution
{
    public bool canJump(int[] nums)
    {
        // Raj Thomas 26th May 2026 2:52PM IST

        int[] dp = new int[nums.Length];
        Array.Fill(dp, -1);

        bool result = helper(nums, 0, dp);
        return result;
    }

    private bool helper(int[] nums, int idx, int[] dp) {

        if(idx >= nums.Length - 1) return true;

        if(dp[idx] != -1) return dp[idx] == 1;

        int maxJump = nums[idx];

        for(int j = 1; j <= maxJump; j++) {

            bool result = helper(nums, idx + j, dp);
            if(result) {
                dp[idx] = 1;
                return true;
            }
        }

        dp[idx] = 0;
        return false;

    }
}
```

